with cleaned as (select *, case when browser in ('Firefox', 'Edge') then 'Group A' else 'Other' end as browser_group, coalesce(browser, 'NONE') as browser_clean from sessions where started_at >= to_date('2023-04-04') and customer_id is null), with_gaps as (select *, case when started_at - lag(started_at) over (partition by browser order by started_at, id) > interval '30' day then 1 else 0 end as is_new_session from cleaned), islands as (select id, browser, started_at, country, browser_clean, sum(is_new_session) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as session_no from with_gaps) select country, count(distinct id) as distinct_ids, count(*) filter (where browser = 'Chrome') as chrome_rows, round(sum(session_no) / nullif(count(case when browser = 'Safari' then 1 end), 0), 2) as session_no_per_safari, count(distinct country) as distinct_countries, avg(session_no) as avg_session_no, sort_array(collect_set(country)) as country_list from islands group by 1 order by country nulls first;
